#include <stack>
#include <vector>
#include <list>

// Use default (std::deque)
std::stack<int> s1;

// Explicitly use std::vector for better cache locality
std::stack<int, std::vector<int>> s2;

// Explicitly use std::list (valid, usually slower)
std::stack<int, std::list<int>> s3;

int main() {
    s2.push(42);
    s3.push(99);
}
